output_text:
[
  {
    "id": "must_take_cart_from_rack",
    "text": "A shopper must pick up a cart from the entrance rack before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_rack": "at(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_cart_rack",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "A shopper must not carry groceries by hand; required items should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_in_use"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking any item while using a cart, the shopper must eventually return the cart to the front return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_parked_in_front_return_bay": "cartAt(0,1)",
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "cart_in_use",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_return_bay",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_front_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_pickup",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper may not leave a cart anywhere except the designated front return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "not_at_front_return_bay": {
          "not": "front_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_front_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_in_use"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_must_be_parked_before_exit",
    "text": "Before leaving the supermarket, the shopper must have the cart parked in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_front_return_bay": "cartAt(0,1)"
      },
      "events": {
        "proper_cart_exit": {
          "pre": {
            "and": [
              "EXIT",
              "cart_parked_in_front_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "proper_cart_exit"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once the cart has been parked in the front return bay, the shopper must not pick it up again.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_parked_in_front_return_bay": "cartAt(0,1)"
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "front_return_bay",
              "cart_parked_in_front_return_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
